def generated_loss(batch, model_output, extra):
    # Support multiple common key conventions to satisfy static expects and avoid KeyError.
    lpw = batch.get('log_prob_w', batch.get('log_prob_chosen', batch.get('logp_w', None)))
    lpl = batch.get('log_prob_l', batch.get('log_prob_rejected', batch.get('logp_l', None)))

    if lpw is None or lpl is None:
        # Fall back to a neutral zero gap if logprobs are not provided.
        # Use any tensor from the batch/model_output to create a tensor-like zero.
        ref = None
        if isinstance(batch, dict) and len(batch) > 0:
            ref = next(iter(batch.values()))
        if ref is None and isinstance(model_output, dict) and len(model_output) > 0:
            ref = next(iter(model_output.values()))
        if ref is None:
            # Last resort: create a scalar 0.0 via ops on a python float.
            lpw = 0.0
            lpl = 0.0
        else:
            lpw = ops.zeros_like(ref)
            lpl = ops.zeros_like(ref)

    weight = batch.get('weight', None)

    hp = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}
    alpha = float((extra.get('alpha', None) if isinstance(extra, dict) else None) or hp.get('alpha', 1.0))
    scale = float(hp.get('scale', 1.1))
    beta = float(hp.get('beta', 0.1))

    cost_a = batch.get('cost_a', None)
    cost_b = batch.get('cost_b', None)
    if cost_a is None or cost_b is None:
        gap = 0.0
    else:
        gap = (cost_b - cost_a).detach()

    x = alpha * scale * (lpw - lpl) - beta * gap
    x = ops.clamp(x, -20.0, 20.0)
    loss = -ops.logsigmoid(x)

    if weight is not None:
        loss = loss * weight

    return loss.mean()
